/**
 * Noise KK Go ↔ JS interop test.
 *
 * Loads go-shared/pairingcrypto/testdata/noise_kk_vectors.json (generated by
 * flynn/noise with deterministic ephemerals) and replays each vector through
 * the mobile's hand-rolled Noise implementation. Any protocol deviation
 * (missed MixHash steps, wrong pre-message order, AEAD AD drift, misoriented
 * Split output) produces a byte-level diff on msg1 / msg2 / transport frames
 * — the exact class of bug that the Go-only E2E test cannot catch, and that
 * users hit as "handshake: HTTP 400 (handshake_failed)" on the retry screen.
 */

import { generateKeyPairFromSeed } from '@stablelib/x25519';
import { newKKInitiator, newKKResponder } from '../noise';
import type { Identity } from '../identity';

// The fixture lives under go-shared/ so Go tests can regenerate it without
// bouncing through mobile/. require() resolves the path relative to this file.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const VECTORS: NoiseKKVector[] = require('../../../../go-shared/pairingcrypto/testdata/noise_kk_vectors.json');

interface NoiseKKVector {
  initiator_static_priv_hex: string;
  initiator_static_pub_hex: string;
  responder_static_priv_hex: string;
  responder_static_pub_hex: string;
  initiator_ephemeral_priv_hex: string;
  initiator_ephemeral_pub_hex: string;
  responder_ephemeral_priv_hex: string;
  responder_ephemeral_pub_hex: string;
  payload1_hex: string;
  payload2_hex: string;
  msg1_hex: string;
  msg2_hex: string;
  initiator_to_responder_plain_hex: string;
  initiator_to_responder_cipher_hex: string;
  responder_to_initiator_plain_hex: string;
  responder_to_initiator_cipher_hex: string;
}

function fromHex(hex: string): Uint8Array {
  if (hex.length === 0) return new Uint8Array(0);
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

function staticIdentity(xPrivHex: string, xPubHex: string): Identity {
  // Noise KK doesn't use the ed keypair at runtime — we fill in with derived
  // values so the Identity type is satisfied. The fixture never exercises ed.
  const xPriv = fromHex(xPrivHex);
  const xPub = fromHex(xPubHex);
  return {
    xPriv,
    xPub,
    edPriv: new Uint8Array(64),
    edPub: new Uint8Array(32),
  };
}

describe('Noise KK interop — Go ↔ JS', () => {
  const vectors: NoiseKKVector[] = VECTORS;

  it('fixture exists and has vectors', () => {
    expect(vectors.length).toBeGreaterThan(0);
  });

  it('derived ephemeral pubs match Go-computed ones', () => {
    for (const v of vectors) {
      const iEphPub = generateKeyPairFromSeed(
        fromHex(v.initiator_ephemeral_priv_hex),
      ).publicKey;
      const rEphPub = generateKeyPairFromSeed(
        fromHex(v.responder_ephemeral_priv_hex),
      ).publicKey;
      expect(toHex(iEphPub)).toBe(v.initiator_ephemeral_pub_hex);
      expect(toHex(rEphPub)).toBe(v.responder_ephemeral_pub_hex);
    }
  });

  it('JS initiator produces byte-identical msg1 for each vector', () => {
    const mismatches: string[] = [];
    vectors.forEach((v, i) => {
      const self = staticIdentity(
        v.initiator_static_priv_hex,
        v.initiator_static_pub_hex,
      );
      const init = newKKInitiator(self, fromHex(v.responder_static_pub_hex), {
        ephemeralPriv: fromHex(v.initiator_ephemeral_priv_hex),
      });
      const msg1 = init.writeMessage(fromHex(v.payload1_hex));
      const got = toHex(msg1);
      if (got !== v.msg1_hex) {
        mismatches.push(`vector ${i}:\n  got  ${got}\n  want ${v.msg1_hex}`);
      }
    });
    expect(mismatches).toEqual([]);
  });

  it('JS responder decodes Go msg1 and produces byte-identical msg2', () => {
    const mismatches: string[] = [];
    vectors.forEach((v, i) => {
      const self = staticIdentity(
        v.responder_static_priv_hex,
        v.responder_static_pub_hex,
      );
      const resp = newKKResponder(self, fromHex(v.initiator_static_pub_hex), {
        ephemeralPriv: fromHex(v.responder_ephemeral_priv_hex),
      });
      const gotPayload1 = resp.readMessage(fromHex(v.msg1_hex));
      if (toHex(gotPayload1) !== v.payload1_hex) {
        mismatches.push(
          `vector ${i} payload1 mismatch:\n  got  ${toHex(gotPayload1)}\n  want ${v.payload1_hex}`,
        );
      }
      const msg2 = resp.writeMessage(fromHex(v.payload2_hex));
      if (toHex(msg2) !== v.msg2_hex) {
        mismatches.push(
          `vector ${i} msg2 mismatch:\n  got  ${toHex(msg2)}\n  want ${v.msg2_hex}`,
        );
      }
    });
    expect(mismatches).toEqual([]);
  });

  it('JS initiator + responder post-handshake ciphers match Go frames', () => {
    const failures: string[] = [];
    vectors.forEach((v, i) => {
      const initSelf = staticIdentity(
        v.initiator_static_priv_hex,
        v.initiator_static_pub_hex,
      );
      const respSelf = staticIdentity(
        v.responder_static_priv_hex,
        v.responder_static_pub_hex,
      );

      const init = newKKInitiator(initSelf, fromHex(v.responder_static_pub_hex), {
        ephemeralPriv: fromHex(v.initiator_ephemeral_priv_hex),
      });
      const resp = newKKResponder(respSelf, fromHex(v.initiator_static_pub_hex), {
        ephemeralPriv: fromHex(v.responder_ephemeral_priv_hex),
      });

      init.writeMessage(fromHex(v.payload1_hex));
      resp.readMessage(fromHex(v.msg1_hex));
      const msg2 = resp.writeMessage(fromHex(v.payload2_hex));
      init.readMessage(msg2);

      const initCipher = init.cipher();
      const respCipher = resp.cipher();
      if (!initCipher || !respCipher) {
        failures.push(`vector ${i}: cipher pair unavailable`);
        return;
      }

      // initiator → responder: must byte-match Go's ciphertext.
      const ctOut = initCipher.encrypt(fromHex(v.initiator_to_responder_plain_hex));
      if (toHex(ctOut) !== v.initiator_to_responder_cipher_hex) {
        failures.push(
          `vector ${i} initiator→responder ct mismatch:\n  got  ${toHex(ctOut)}\n  want ${v.initiator_to_responder_cipher_hex}`,
        );
      }
      const ptIn = respCipher.decrypt(fromHex(v.initiator_to_responder_cipher_hex));
      if (toHex(ptIn) !== v.initiator_to_responder_plain_hex) {
        failures.push(
          `vector ${i} responder decrypt(Go ct) mismatch:\n  got  ${toHex(ptIn)}\n  want ${v.initiator_to_responder_plain_hex}`,
        );
      }

      // responder → initiator.
      const ctBack = respCipher.encrypt(fromHex(v.responder_to_initiator_plain_hex));
      if (toHex(ctBack) !== v.responder_to_initiator_cipher_hex) {
        failures.push(
          `vector ${i} responder→initiator ct mismatch:\n  got  ${toHex(ctBack)}\n  want ${v.responder_to_initiator_cipher_hex}`,
        );
      }
      const ptBack = initCipher.decrypt(fromHex(v.responder_to_initiator_cipher_hex));
      if (toHex(ptBack) !== v.responder_to_initiator_plain_hex) {
        failures.push(
          `vector ${i} initiator decrypt(Go ct) mismatch:\n  got  ${toHex(ptBack)}\n  want ${v.responder_to_initiator_plain_hex}`,
        );
      }
    });
    expect(failures).toEqual([]);
  });
});
